// Small preview controller. Three.js is fetched only after a 3D request.
const original=document.querySelector('#config-board');
if(original){
 const host=document.createElement('div');host.className='keyboard-studio picture-first';original.before(host);original.classList.add('studio-fallback');
 const modes=document.createElement('div');modes.className='preview-modes';modes.setAttribute('role','group');modes.setAttribute('aria-label','Keyboard preview');modes.innerHTML='<button type="button" data-mode="picture" aria-pressed="true">Product photo</button><button type="button" data-mode="model" aria-pressed="false">3D view</button><span>EN + RU</span>';host.append(modes,original);
 const modelButton=modes.querySelector('[data-mode="model"]');let viewer=null,request=0,active=false,modulePromise=null,lightweight=false;
 function dispose(){const old=viewer;viewer=null;old?.dispose();}
 function buttons(){host.classList.toggle('has-3d',active);modes.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String((b.dataset.mode==='model')===active)));const caption=document.querySelector('.art-caption span:last-child');if(caption)caption.textContent=active?'3D CONCEPT VIEW · EN + RU':globalThis.getKeyboardDesign?.().m==='mountain'?'REFERENCE PHOTO · EN + RU':'PRODUCT PICTURE · EN + RU';}
 function done(){modelButton.textContent='3D view';modelButton.removeAttribute('aria-busy');}
 function photo(){request++;active=false;dispose();done();buttons();}
 async function model(){const token=++request;modelButton.textContent='Loading 3D…';modelButton.setAttribute('aria-busy','true');let timer;
  try{
   let Viewer=LightweightViewer;
   if(!lightweight){try{modulePromise??=import('./keyboard-3d.js?v=phone-perf');const module=await Promise.race([modulePromise,new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error('3D download timeout')),8000);})]);Viewer=module.KeyboardViewer;}catch{lightweight=true;}finally{clearTimeout(timer);}}
   if(token!==request)return;
   dispose();try{viewer=new Viewer(host);if(!viewer.renderer&&Viewer!==LightweightViewer)throw Error('WebGL unavailable');active=true;buttons();viewer.renderNow();}catch{dispose();if(token!==request)return;lightweight=true;viewer=new LightweightViewer(host);active=true;buttons();viewer.renderNow();}
  }finally{clearTimeout(timer);if(token===request)done();}
 }
 modes.addEventListener('click',e=>{const button=e.target.closest('[data-mode]');if(!button)return;if(button.dataset.mode==='picture')photo();else if(!modelButton.hasAttribute('aria-busy'))model();});
 host.addEventListener('viewer-context-lost',()=>{request++;dispose();lightweight=true;viewer=new LightweightViewer(host);active=true;viewer.renderNow();done();buttons();});
 let queued=false;function sync(){if(queued)return;queued=true;queueMicrotask(()=>{queued=false;const state=globalThis.getKeyboardDesign?.();if(!state)return;for(const [id,text] of [['recap-case',state.m==='mountain'?globalThis.mountainDesign.variants[state.v||0].name:['Silver aluminum','Ivory','Deep blue','Black'][state.c]],['recap-color',state.m==='mountain'?'Cream + mountain artwork':['Milk','Denim blue','Sand honey','Ice blue','Muted wine','Graphite'][state.k]],['recap-switch',{linear:'Linear',tactile:'Tactile',clicky:'Clicky'}[state.s]]]){const el=document.getElementById(id);if(el)el.textContent=text;}if(viewer?.model!==(state.m||'character')&&viewer){if(active)model();else dispose();}else if(active)viewer?.update(state);buttons();});}
 document.addEventListener('click',sync);document.addEventListener('change',sync);
 document.addEventListener('visibilitychange',()=>{if(document.hidden)photo();});
 buttons();sync();
}

// A real layered, rotatable keyboard for devices that cannot create WebGL.
// No animation loop, canvas, textures, external files or WebGL context.
class LightweightViewer{
 constructor(host){this.host=host;this.model=globalThis.getKeyboardDesign?.().m||'character';this.stage=document.createElement('div');this.stage.className='viewer-stage lite-stage';this.stage.tabIndex=0;this.stage.setAttribute('role','img');this.stage.setAttribute('aria-label','3D keyboard. Drag or use arrow keys to rotate.');this.board=document.createElement('div');this.board.className='lite-keyboard';this.stage.append(this.board);this.toolbar=document.createElement('div');this.toolbar.className='viewer-toolbar';this.toolbar.innerHTML='<span class="viewer-hint"><span class="live-dot"></span>3D VIEW <span class="drag-hint">/ DRAG TO ROTATE</span></span><button type="button" class="viewer-reset">Reset angle ↺</button>';host.append(this.stage,this.toolbar);this.rx=25;this.ry=0;this.rz=-3;this.pointer=null;this.toolbar.querySelector('button').onclick=()=>{this.rx=25;this.ry=0;this.rz=-3;this.renderNow();};this.stage.addEventListener('pointerdown',e=>{this.pointer={id:e.pointerId,x:e.clientX,y:e.clientY,rx:this.rx,ry:this.ry};this.stage.setPointerCapture(e.pointerId);});this.stage.addEventListener('pointermove',e=>{if(!this.pointer||e.pointerId!==this.pointer.id)return;this.ry=Math.max(-40,Math.min(40,this.pointer.ry+(e.clientX-this.pointer.x)*.3));this.rx=Math.max(5,Math.min(65,this.pointer.rx-(e.clientY-this.pointer.y)*.3));this.renderNow();});for(const event of ['pointerup','pointercancel'])this.stage.addEventListener(event,()=>{this.pointer=null;});this.stage.addEventListener('keydown',e=>{if(!e.key.startsWith('Arrow'))return;e.preventDefault();if(e.key==='ArrowLeft')this.ry-=5;if(e.key==='ArrowRight')this.ry+=5;if(e.key==='ArrowUp')this.rx-=5;if(e.key==='ArrowDown')this.rx+=5;this.rx=Math.max(5,Math.min(65,this.rx));this.ry=Math.max(-40,Math.min(40,this.ry));this.renderNow();});this.observer=new ResizeObserver(()=>this.renderNow());this.observer.observe(this.stage);this.update(globalThis.getKeyboardDesign());}
 update(state){const next=JSON.stringify([state.m,state.v,state.c,state.k]);if(next===this.last)return;this.last=next;const appearance=globalThis.getKeyboardAppearance(),mountain=this.model==='mountain',variant=globalThis.mountainDesign?.variants[state.v||0],caps=appearance.keycaps[state.k],finish=mountain?variant.hex:state.c===1?'#e6ddce':appearance.finishes[state.c].hex,keys=mountain?globalThis.mountainDesign.layout():globalThis.CHARACTER_MODEL.keys;this.board.style.setProperty('--case',finish);this.board.replaceChildren();const esc=text=>text.replaceAll('&','&amp;').replaceAll('<','&lt;');for(const key of keys){const el=document.createElement('div');el.className='lite-key';el.style.cssText=`left:${key.x}px;top:${key.y}px;width:${key.w}px;height:${key.h}px;--cap:${mountain?(key.accent?variant.hex:globalThis.mountainDesign.cream):caps.hex};--legend:${mountain?(key.accent?globalThis.mountainDesign.cream:variant.hex):caps.ink};`;const [en,ru]=key.label.split(' ');const swoosh=['Esc','F4','F8','F12','Tab','Caps','CapsLock','Shift','Enter','Backspace','↑','←','↓','→'].includes(key.label)||['Q','W','A','S','D'].includes(en);const path=mountain?globalThis.mountainDesign.art(100,40):key.label==='SPACE'?'M4 34C28 14 40 46 77 12C99 -1 103 29 87 34Z M81 20a6 4 0 1 0 12 0a6 4 0 1 0 -12 0':'M20 33Q79 36 92 18Q100 40 45 35Z';el.innerHTML=(key.label==='SPACE'?'':`<span class="lite-en" style="font-size:${en.length>5?8:en.length>3?9:12}px">${esc(en)}</span>${ru?`<span class="lite-ru">${esc(ru)}</span>`:''}`)+((key.label==='SPACE'||swoosh)?`<svg viewBox="0 0 100 40" preserveAspectRatio="none" aria-hidden="true"><path d="${path}" fill="currentColor" fill-rule="evenodd"/></svg>`:'');this.board.append(el);}if(mountain){const screen=document.createElement('div');screen.className='lite-screen';screen.textContent='85%';this.board.append(screen);}this.renderNow();}
 renderNow(){if(this.disposed)return;const scale=Math.min((this.stage.clientWidth-12)/900,this.stage.clientHeight/470);this.board.style.transform=`translate(-50%,-50%) scale(${Math.max(.1,scale)}) rotateX(${this.rx}deg) rotateY(${this.ry}deg) rotateZ(${this.rz}deg)`;this.ready=true;}
 dispose(){this.disposed=true;this.observer.disconnect();this.stage.remove();this.toolbar.remove();}
}
